A busca binária encontra um valor numa lista ORDENADA dividindo o intervalo de busca pela metade a cada passo. O custo é O(log n).

def busca_binaria(lista, alvo):
    inicio, fim = 0, len(lista) - 1
    while inicio <= fim:
        meio = (inicio + fim) // 2
        if lista[meio] == alvo:
            return meio          # achou: devolve a posição
        if lista[meio] < alvo:
            inicio = meio + 1    # o alvo está na metade da direita
        else:
            fim = meio - 1       # o alvo está na metade da esquerda
    return -1                    # não está na lista

print(busca_binaria([2, 5, 8, 12, 16, 23], 12))  # 3

Erro comum: usar a busca binária numa lista que não está ordenada.

from abc import ABC, abstractmethod
import math

class Forma(ABC):
    @abstractmethod
    def area(self) -> float:
        ...

class Retangulo(Forma):
    def __init__(self, largura, altura):
        self.largura = largura
        self.altura = altura

    def area(self):
        return self.largura * self.altura

class Circulo(Forma):
    def __init__(self, raio):
        self.raio = raio

    def area(self):
        return math.pi * self.raio ** 2

formas = [Retangulo(2, 3), Circulo(1)]
for forma in formas:
    print(type(forma).__name__, round(forma.area(), 2))

O laço não precisa saber o tipo de cada forma: cada uma sabe calcular a própria área. Tentar instanciar Forma diretamente gera erro, porque ela é abstrata.

#include <stdlib.h>
#include <string.h>

#define TAMANHO 101  /* um número primo ajuda a espalhar as chaves */

typedef struct No {
    char *chave;
    int valor;
    struct No *proximo;
} No;

static No *tabela[TAMANHO];

static unsigned long hash(const char *s) {
    unsigned long h = 5381;  /* função djb2 */
    int c;
    while ((c = (unsigned char)*s++))
        h = h * 33 + c;
    return h % TAMANHO;
}

void inserir(const char *chave, int valor) {
    unsigned long i = hash(chave);
    for (No *no = tabela[i]; no; no = no->proximo) {
        if (strcmp(no->chave, chave) == 0) {
            no->valor = valor;  /* chave já existe: atualiza */
            return;
        }
    }
    No *novo = malloc(sizeof(No));
    novo->chave = malloc(strlen(chave) + 1);
    strcpy(novo->chave, chave);
    novo->valor = valor;
    novo->proximo = tabela[i];  /* insere no início da lista */
    tabela[i] = novo;
}

int buscar(const char *chave, int *valor) {
    for (No *no = tabela[hash(chave)]; no; no = no->proximo) {
        if (strcmp(no->chave, chave) == 0) {
            *valor = no->valor;
            return 1;
        }
    }
    return 0;
}

Em código de verdade, confira se o malloc devolveu NULL e libere a memória no final.

Ao longo de uma linha de corrente:
p + ½ · ρ · v² + ρ · g · z = constante

Vale quando o escoamento é:
- permanente (não muda com o tempo);
- incompressível (densidade constante);
- sem atrito (viscosidade desprezível);
- sem bombas, turbinas ou troca de calor entre os pontos.

Combine com a conservação da massa (continuidade): A1 · v1 = A2 · v2. Num estreitamento, a velocidade aumenta e a pressão cai (efeito Venturi).

Se houver perdas por atrito ou máquinas no trecho, use a equação da energia com os termos de perda de carga e de altura da bomba ou turbina.
